/* From Uiverse.io by vinodjangid07 - Tags: switch, toggle, volume, click effect */
/* The switch - the box around the speaker*/
.__UIV_SCOPE__ .toggleSwitch {
  width: 50px;
  height: 50px;
  position: relative;
  display: flex;
  align-items: center;
  justify-content: center;
  background-color: rgb(39, 39, 39);
  border-radius: 50%;
  cursor: pointer;
  transition-duration: .3s;
  box-shadow: 2px 2px 10px rgba(0, 0, 0, 0.13);
  overflow: hidden;
}

/* Hide default HTML checkbox */
.__UIV_SCOPE__ #checkboxInput {
  display: none;
}

.__UIV_SCOPE__ .bell {
  width: 18px;
}

.__UIV_SCOPE__ .bell path {
  fill: white;
}

.__UIV_SCOPE__ .speaker {
  width: 100%;
  height: 100%;
  display: flex;
  align-items: center;
  justify-content: center;
  z-index: 2;
  transition-duration: .3s;
}

.__UIV_SCOPE__ .speaker svg {
  width: 18px;
}

.__UIV_SCOPE__ .mute-speaker {
  position: absolute;
  width: 100%;
  height: 100%;
  display: flex;
  align-items: center;
  justify-content: center;
  opacity: 0;
  z-index: 3;
  transition-duration: .3s;
}

.__UIV_SCOPE__ .mute-speaker svg {
  width: 18px;
}

.__UIV_SCOPE__ #checkboxInput:checked +.toggleSwitch .speaker {
  opacity: 0;
  transition-duration: .3s;
}

.__UIV_SCOPE__ #checkboxInput:checked +.toggleSwitch .mute-speaker {
  opacity: 1;
  transition-duration: .3s;
}

.__UIV_SCOPE__ #checkboxInput:active + .toggleSwitch {
  transform: scale(0.7);
}

.__UIV_SCOPE__ #checkboxInput:hover + .toggleSwitch {
  background-color: rgb(61, 61, 61);
}
